style.css:
@-moz-document domain("instagram.com") {
/* Fondo fijo con Vermeil */
    body {
        background: url("https://wall.alphacoders.com/big.php?i=1262319") no-repeat center center fixed !important;
        background-size: cover !important;
        font-family: 'Segoe UI', sans-serif !important;
        color: #d6b3ff !important;
    }

    /* Hacer todo transparente */
    header, nav, main, section, div, article, aside, footer {
        background: transparent !important;
        box-shadow: none !important;
        border: none !important;
    }

    /* Texto visible y elegante */
    h1, h2, h3, h4, h5, h6, p, span, a, button, input, label {
        color: #d6b3ff !important;
        font-family: 'Segoe UI', sans-serif !important;
        font-size: 1rem !important;
    }

    /* Botones e íconos */
    svg, path {
        fill: #d6b3ff !important;
    }

    /* Efecto hover para resaltar texto */
    a:hover, button:hover, label:hover {
        color: #ffffff !important;
        text-shadow: 0 0 6px #d6b3ff !important;
    }

    /* Cuadro flotante al pasar el ratón por texto */
    a:hover::after, span:hover::after, label:hover::after {
        content: attr(title);
        position: absolute;
        background-color: rgba(0, 0, 0, 0.7);
        color: #ffffff;
        padding: 6px 10px;
        border-radius: 6px;
        font-size: 0.9rem;
        white-space: nowrap;
        z-index: 9999;
        top: 100%;
        left: 0;
        margin-top: 4px;
        box-shadow: 0 2px 6px rgba(0,0,0,0.5);
    }
}
